export const meta = {
  name: 'witness-probe-2',
  description: 'Second harness probe: is the Workflow tool call itself visible to hooks?',
  phases: [
    { title: 'Probe2', detail: 'one trivial agent, no tools' },
  ],
}

phase('Probe2')

const one = await agent('This is a harness instrumentation probe, not a real task. Do not read files, run commands, or use any tools. Reply with exactly the single word: CHARLIE', { label: 'probe-charlie', phase: 'Probe2' })

log(`probe2 returned: ${one}`)
return { one }
